const HELPER:&str="/usr/libexec/milmit-surfshark-helper";
const STATE:&str="/run/milmit-surfshark/restricted.state";
const LIVE:&str="/run/milmit-surfshark/live.state";
const DEFAULT_DNS:&str="162.252.172.57,149.154.159.92";

#[derive(Clone)]
struct Settings{mss:u32,dns:String,hotspot_vpn:bool,hotspot_iface:String,recover:bool,kill:bool,routing:String}
impl Default for Settings{fn default()->Self{Self{mss:1200,dns:DEFAULT_DNS.into(),hotspot_vpn:true,hotspot_iface:"auto".into(),recover:true,kill:true,routing:"vpn_all".into()}}}

fn cfg_dir()->PathBuf{std::env::var("XDG_CONFIG_HOME").map(PathBuf::from).or_else(|_|std::env::var("HOME").map(|h|PathBuf::from(h).join(".config"))).unwrap_or_else(|_|PathBuf::from(".")).join("milmit-surfshark")}
fn cfg_path()->PathBuf{cfg_dir().join("settings.conf")}
fn user_path()->PathBuf{cfg_dir().join("username")}
fn load_settings()->Settings{let mut s=Settings::default();if let Ok(t)=fs::read_to_string(cfg_path()){for l in t.lines(){if let Some((k,v))=l.split_once('='){match k{"mss"=>if let Ok(n)=v.parse(){s.mss=n},"dns"=>s.dns=v.into(),"hotspot_vpn"=>s.hotspot_vpn=v=="1","hotspot_iface"=>s.hotspot_iface=v.into(),"recover"=>s.recover=v=="1","kill"=>s.kill=v=="1","routing"=>s.routing=v.into(),_=>{}}}}}s}
fn save_settings(s:&Settings){let p=cfg_path();if let Some(d)=p.parent(){let _=fs::create_dir_all(d);}let _=fs::write(p,format!("mss={}\ndns={}\nhotspot_vpn={}\nhotspot_iface={}\nrecover={}\nkill={}\nrouting={}\n",s.mss,s.dns,s.hotspot_vpn as u8,s.hotspot_iface,s.recover as u8,s.kill as u8,s.routing));}
fn saved_user()->String{fs::read_to_string(user_path()).unwrap_or_default().trim().to_string()}
fn save_user(v:&str){let p=user_path();if let Some(d)=p.parent(){let _=fs::create_dir_all(d);}let _=fs::write(p,v);}
fn value(path:&str,key:&str)->Option<String>{let t=fs::read_to_string(path).ok()?;t.lines().find_map(|l|{let(k,v)=l.split_once('=')?;(k==key).then(||v.trim().to_string())})}
fn active()->bool{value(STATE,"VIRTUAL_IP").map(|v|Command::new("ip").args(["-4","addr","show"]).output().ok().map(|o|String::from_utf8_lossy(&o.stdout).contains(&v)).unwrap_or(false)).unwrap_or(false)}
fn helper(args:&[&str])->String{match Command::new("pkexec").arg(HELPER).args(args).output(){Ok(o)=>{let mut t=String::from_utf8_lossy(&o.stdout).to_string();t.push_str(&String::from_utf8_lossy(&o.stderr));t},Err(e)=>e.to_string()}}
fn candidate_ips(host:&str)->Vec<String>{let mut v=Vec::new();if host=="ee-tll.prod.surfshark.com"{v.push("185.174.159.123".into())}for x in bundled_for_host(host){if !v.iter().any(|e|e==x){v.push((*x).into())}}v}
fn connect_vpn(host:&str,user:&str,password:&str,s:&Settings)->(bool,String){let mut log=String::new();for ip in candidate_ips(host){let m=s.mss.to_string();let hotspot=if s.hotspot_vpn{"1"}else{"0"};let recover=if s.recover{"1"}else{"0"};let kill=if s.kill{"1"}else{"0"};let mut c=match Command::new("pkexec").arg(HELPER).args(["connect",&ip,user,&m,&s.dns,hotspot,recover,&s.hotspot_iface,kill,&s.routing,"","",host]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn(){Ok(c)=>c,Err(e)=>return(false,e.to_string())};if let Some(stdin)=c.stdin.as_mut(){let _=writeln!(stdin,"{password}");}match c.wait_with_output(){Ok(o)=>{let t=format!("{}{}",String::from_utf8_lossy(&o.stdout),String::from_utf8_lossy(&o.stderr));log.push_str(&format!("\n[{ip}]\n{t}\n"));if o.status.success()&&t.contains("Data-path test: OK"){return(true,log)}},Err(e)=>log.push_str(&format!("{e}\n"))}}(false,log)}

