fn title_box(t:&str,s:&str)->gtk::Box{let b=gtk::Box::new(Orientation::Vertical,2);b.append(&gtk::Label::builder().label(t).halign(gtk::Align::Start).css_classes(["row-title"]).build());if !s.is_empty(){b.append(&gtk::Label::builder().label(s).halign(gtk::Align::Start).wrap(true).css_classes(["row-sub"]).build())}b}
fn page_header(stack:&gtk::Stack,title:&str)->gtk::Box{let b=gtk::Box::new(Orientation::Horizontal,8);b.add_css_class("top");let back=gtk::Button::from_icon_name("go-previous-symbolic");back.add_css_class("back");let st=stack.clone();back.connect_clicked(move |_|st.set_visible_child_name("home"));b.append(&back);b.append(&gtk::Label::builder().label(title).hexpand(true).halign(gtk::Align::Start).css_classes(["brand"]).build());b}
fn nav_row(title:&str,sub:&str)->(gtk::Button,gtk::Box){let button=gtk::Button::new();button.add_css_class("row");button.set_hexpand(true);let row=gtk::Box::new(Orientation::Horizontal,10);row.append(&title_box(title,sub));let spacer=gtk::Box::new(Orientation::Horizontal,0);spacer.set_hexpand(true);row.append(&spacer);row.append(&gtk::Image::from_icon_name("go-next-symbolic"));button.set_child(Some(&row));let wrap=gtk::Box::new(Orientation::Vertical,0);wrap.append(&button);(button,wrap)}
fn switch_row(title:&str,sub:&str,on:bool)->(gtk::Box,gtk::Switch){let row=gtk::Box::new(Orientation::Horizontal,10);row.add_css_class("row");row.append(&title_box(title,sub));let spacer=gtk::Box::new(Orientation::Horizontal,0);spacer.set_hexpand(true);row.append(&spacer);let sw=gtk::Switch::builder().active(on).valign(gtk::Align::Center).build();row.append(&sw);(row,sw)}

