let settings_conn=settings.clone();let sel_conn=selected.clone();let status_c=status.clone();let sub_c=status_sub.clone();let shield_c=shield.clone();let connect_c=connect.clone();connect.connect_clicked(move |_|{if active(){let _=helper(&["disconnect"]);status_c.set_label("UNSECURED CONNECTION");sub_c.set_label("Connect to protect your traffic");shield_c.remove_css_class("shield-on");connect_c.set_label("Secure my connection");connect_c.remove_css_class("danger");connect_c.add_css_class("primary");return}let user=saved_user();if user.is_empty(){status_c.set_label("ADD CREDENTIALS");sub_c.set_label("Open Settings and save your Surfshark service username first");return}let id=sel_conn.borrow().clone();let Some(loc)=by_id(&id)else{return};status_c.set_label("CONNECTING…");sub_c.set_label(&format!("Securing via {}",loc.label));shield_c.add_css_class("shield-busy");let s=settings_conn.borrow().clone();let host=loc.host.to_string();let status2=status_c.clone();let sub2=sub_c.clone();let shield2=shield_c.clone();let button2=connect_c.clone();let (tx,rx)=std::sync::mpsc::channel();thread::spawn(move ||{let r=connect_vpn(&host,&user,"",&s);let _=tx.send(r);});glib::timeout_add_local(Duration::from_millis(150),move ||match rx.try_recv(){Ok((ok,_log))=>{shield2.remove_css_class("shield-busy");if ok{shield2.add_css_class("shield-on");status2.set_label("SECURE CONNECTION");sub2.set_label("Your traffic is protected");button2.set_label("Disconnect");button2.remove_css_class("primary");button2.add_css_class("danger")}else{status2.set_label("CONNECTION FAILED");sub2.set_label("Open Diagnostics for details")}glib::ControlFlow::Break},Err(std::sync::mpsc::TryRecvError::Empty)=>glib::ControlFlow::Continue,Err(_)=>glib::ControlFlow::Break});});

// Credentials are deliberately kept on a dedicated small modal-like page.
